from phase0_v2.calibration.audit_helpers import measure_fix_errors
from phase0_v2.calibration._shared import load_records
import nltk, re

records = load_records('phase0_v2/data/results/google_gemma-3-27b-it_results.jsonl')

def _split_sentences(text):
    return [s.strip() for s in nltk.sent_tokenize(text.strip()) if len(s.strip()) > 5]

def _apply_truncation_guard(sentences):
    if len(sentences) > 1:
        last = sentences[-1].rstrip()
        if not last.endswith(('?', '.', '!', '"', "'", ')', '\u201d', '\u2019')):
            sentences = sentences[:-1]
    return sentences

def _is_all_questions_fixed(r):
    sentences = _split_sentences(r)
    sentences = _apply_truncation_guard(sentences)
    if not sentences:
        return False
    for s in sentences:
        core = re.sub(r'["\u201d\u2019\'\)\]]+$', '', s.rstrip()).rstrip()
        if not core.endswith('?'):
            return False
    return True

def _is_all_statements_fixed(r):
    sentences = _split_sentences(r)
    sentences = _apply_truncation_guard(sentences)
    if not sentences:
        return False
    for s in sentences:
        core = re.sub(r'["\u201d\u2019\'\)\]]+$', '', s.rstrip()).rstrip()
        if core.endswith('?'):
            return False
    return True

fix = measure_fix_errors(records, 'questions_vs_statements', _is_all_questions_fixed, _is_all_statements_fixed)
print(f'old: {fix["old_labels"]}')
print(f'new: {fix["new_labels"]}')
print(f'error_pct: {fix["error_pct"]:.2f}%')
print(f'changed: {fix["changed"]} labels')
